/* ============================ BOOKING STEPPER UI =========================== */

function Stepper({ steps, current }) {
  return (
    <div className="smh-stepper">
      {steps.map((s, i) => (
        <React.Fragment key={s}>
          <div className={`smh-step ${i < current ? "is-done" : ""} ${i === current ? "is-active" : ""}`}>
            <span className="smh-step-dot">{i < current ? <Check size={13} /> : i + 1}</span>
            <span className="smh-step-label">{s}</span>
          </div>
          {i < steps.length - 1 && <span className="smh-step-line" />}
        </React.Fragment>
      ))}
    </div>
  );
}

function DateChips({ dates, blockedDates, selected, onSelect }) {
  return (
    <div className="smh-date-scroll">
      {dates.map((d) => {
        const key = dateKey(d);
        const { weekday, day, month } = dateLabel(d);
        const blocked = blockedDates.includes(key);
        return (
          <button
            key={key}
            disabled={blocked}
            onClick={() => onSelect(key)}
            className={`smh-date-chip ${selected === key ? "is-selected" : ""} ${blocked ? "is-blocked" : ""}`}
          >
            <span className="smh-date-weekday">{weekday}</span>
            <span className="smh-date-day">{day}</span>
            <span className="smh-date-month">{month}</span>
            {blocked && <span className="smh-date-closed">Closed</span>}
          </button>
        );
      })}
    </div>
  );
}

/* ============================ DARSHANA BOOKING ============================= */

function useAvailability(bookings, slotConfig) {
  return useCallback(
    (type, date) => {
      const list = type === "darshana" ? slotConfig.darshanaSlots : slotConfig.aartiSlots;
      const dateBlocked = slotConfig.blockedDates.includes(date);
      return list.map((slot) => {
        const slotBlocked =
          dateBlocked ||
          slotConfig.blockedSlots.some((b) => b.date === date && b.type === type && b.slotId === slot.id);
        const booked = bookings
          .filter(
            (b) =>
              b.status !== "cancelled" &&
              b.type === type &&
              b.date === date &&
              (type === "darshana" ? b.time === slot.time : b.aartiSlotId === slot.id)
          )
          .reduce((sum, b) => sum + b.people, 0);
        const remaining = Math.max(0, slot.capacity - booked);
        return { ...slot, booked, remaining, full: slotBlocked || remaining <= 0, blocked: slotBlocked };
      });
    },
    [bookings, slotConfig]
  );
}

function BookingDetailsForm({ people, setPeople, name, setName, phone, setPhone, maxPeople, errors }) {
  return (
    <div>
      <Field label="Full Name" error={errors.name}>
        <TextInput placeholder="e.g. Ramesh Kumar" value={name} onChange={(e) => setName(e.target.value)} />
      </Field>
      <Field label="Mobile Number" error={errors.phone} hint="10-digit Indian mobile number">
        <TextInput placeholder="e.g. 9876543210" value={phone} maxLength={10} inputMode="numeric" onChange={(e) => setPhone(e.target.value.replace(/\D/g, ""))} />
      </Field>
      <Field label="Number of People" error={errors.people} hint={`Maximum ${maxPeople} for this slot`}>
        <div className="smh-stepper-input">
          <button type="button" onClick={() => setPeople(Math.max(1, people - 1))}><ChevronLeft size={16} /></button>
          <span>{people}</span>
          <button type="button" onClick={() => setPeople(Math.min(maxPeople, people + 1))}><ChevronRight size={16} /></button>
        </div>
      </Field>
    </div>
  );
}

function DarshanaBookingPage({ bookings, slotConfig, onBooked, goto }) {
  const [step, setStep] = useState(0);
  const [date, setDate] = useState(null);
  const [slot, setSlot] = useState(null);
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [people, setPeople] = useState(1);
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [banner, setBanner] = useState(null);

  const getAvailability = useAvailability(bookings, slotConfig);
  const dates = useMemo(() => upcomingDates(21), []);
  const slots = date ? getAvailability("darshana", date) : [];

  const selectedSlotFresh = slot ? slots.find((s) => s.id === slot.id) : null;
  const maxPeople = selectedSlotFresh ? Math.max(1, Math.min(10, selectedSlotFresh.remaining)) : 10;

  function validateDetails() {
    const e = {};
    if (!isValidName(name)) e.name = "Please enter a valid full name.";
    if (!isValidPhone(phone)) e.phone = "Please enter a valid 10-digit mobile number.";
    if (people < 1) e.people = "At least 1 person is required.";
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  async function confirmBooking() {
    setSubmitting(true);
    setBanner(null);
    const result = await attemptBooking({
      type: "darshana",
      date,
      time: slot.time,
      aartiSlotId: null,
      aartiName: null,
      name: name.trim(),
      phone: phone.trim(),
      people,
    });
    setSubmitting(false);
    if (result.success) {
      onBooked(result.booking);
      goto("confirmation");
    } else if (result.reason === "duplicate") {
      setBanner("You already have a booking for this date and time slot.");
    } else {
      setBanner("This time slot is currently unavailable. Please select another time or another date.");
      setStep(1);
      setSlot(null);
    }
  }

  const steps = ["Select Date", "Select Time", "Your Details", "Confirm"];

  return (
    <section className="smh-booking-page">
      <div className="smh-container smh-booking-container">
        <div className="text-center mb-8">
          <Eyebrow>DARSHANA BOOKING</Eyebrow>
          <h1 className="smh-h1">Book Your Darshana</h1>
          <p className="smh-body-sm" style={{ color: "var(--ink-soft)" }}>A few quick steps — takes less than a minute.</p>
        </div>

        <Stepper steps={steps} current={step} />

        <Card className="smh-booking-card">
          {banner && (
            <div className="smh-alert smh-alert-warn">
              <AlertTriangle size={17} />
              <span>{banner}</span>
            </div>
          )}

          {step === 0 && (
            <div>
              <p className="smh-step-title"><Calendar size={18} /> Select a Date</p>
              <DateChips dates={dates} blockedDates={slotConfig.blockedDates} selected={date} onSelect={(k) => { setDate(k); setSlot(null); }} />
              <div className="smh-booking-actions">
                <span />
                <Button variant="primary" disabled={!date} onClick={() => setStep(1)} icon={ArrowRight}>Continue</Button>
              </div>
            </div>
          )}

          {step === 1 && (
            <div>
              <p className="smh-step-title"><Clock size={18} /> Select an Available Time — {prettyDate(date)}</p>
              <div className="smh-slot-grid">
                {slots.map((s) => (
                  <button
                    key={s.id}
                    disabled={s.full}
                    onClick={() => setSlot(s)}
                    className={`smh-slot-btn ${slot?.id === s.id ? "is-selected" : ""} ${s.full ? "is-full" : ""}`}
                  >
                    <span className="smh-slot-time">{s.time}</span>
                    <span className="smh-slot-status">{s.full ? "Full" : `${s.remaining} spots left`}</span>
                  </button>
                ))}
              </div>
              <div className="smh-booking-actions">
                <Button variant="ghost" onClick={() => setStep(0)} icon={ChevronLeft}>Back</Button>
                <Button variant="primary" disabled={!slot} onClick={() => setStep(2)} icon={ArrowRight}>Continue</Button>
              </div>
            </div>
          )}

          {step === 2 && (
            <div>
              <p className="smh-step-title"><Users size={18} /> Enter Your Details</p>
              <BookingDetailsForm people={people} setPeople={setPeople} name={name} setName={setName} phone={phone} setPhone={setPhone} maxPeople={maxPeople} errors={errors} />
              <div className="smh-booking-actions">
                <Button variant="ghost" onClick={() => setStep(1)} icon={ChevronLeft}>Back</Button>
                <Button variant="primary" onClick={() => { if (validateDetails()) setStep(3); }} icon={ArrowRight}>Review Booking</Button>
              </div>
            </div>
          )}

          {step === 3 && (
            <div>
              <p className="smh-step-title"><CheckCircle2 size={18} /> Review &amp; Confirm</p>
              <div className="smh-review-list">
                <div><span>Darshana Type</span><b>General Darshana</b></div>
                <div><span>Date</span><b>{prettyDate(date)}</b></div>
                <div><span>Time</span><b>{slot.time}</b></div>
                <div><span>Number of People</span><b>{people}</b></div>
                <div><span>Name</span><b>{name}</b></div>
                <div><span>Mobile Number</span><b>{phone}</b></div>
              </div>
              <div className="smh-booking-actions">
                <Button variant="ghost" onClick={() => setStep(2)} icon={ChevronLeft}>Back</Button>
                <Button variant="primary" onClick={confirmBooking} disabled={submitting} icon={submitting ? RefreshCw : Check}>
                  {submitting ? "Confirming…" : "Confirm Booking"}
                </Button>
              </div>
            </div>
          )}
        </Card>
      </div>
    </section>
  );
}

