function AdminLoginPage({ onLogin, goto }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function submit(e) {
    e.preventDefault();
    setLoading(true);
    setError("");
    const res = await onLogin(username.trim(), password);
    setLoading(false);
    if (!res.success) setError(res.message || "Invalid username or password.");
  }

  return (
    <section className="smh-booking-page">
      <div className="smh-container" style={{ maxWidth: 440 }}>
        <Card className="smh-booking-card">
          <div className="text-center mb-6">
            <div className="smh-admin-lock"><ShieldCheck size={26} /></div>
            <h1 className="smh-h3">Temple Administrator Login</h1>
            <p className="smh-body-sm" style={{ color: "var(--ink-soft)" }}>Authorised access only.</p>
          </div>
          <form onSubmit={submit}>
            {error && (
              <div className="smh-alert smh-alert-error">
                <AlertTriangle size={16} /> <span>{error}</span>
              </div>
            )}
            <Field label="Username">
              <TextInput value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" required />
            </Field>
            <Field label="Password">
              <div style={{ position: "relative" }}>
                <TextInput type={showPw ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password" required />
                <button type="button" onClick={() => setShowPw(!showPw)} className="smh-pw-toggle">
                  {showPw ? <EyeOff size={17} /> : <Eye size={17} />}
                </button>
              </div>
            </Field>
            <Button type="submit" variant="primary" className="w-full justify-center" disabled={loading}>
              {loading ? "Signing in…" : "Sign In"}
            </Button>
          </form>
          <p className="smh-hint-box">
            First time here? Default login is <b>admin</b> / <b>admin123</b>. Please change the password immediately after signing in, from Security settings.
          </p>
          <button className="smh-back-home" onClick={() => goto("home")}><ChevronLeft size={15} /> Back to website</button>
        </Card>
      </div>
    </section>
  );
}

